INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2091JX6', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(2, 11)$ and $(5, 29)$. What is the equation of this line in slope-intercept form?', NULL, $lyceon_json$[{"key":"A","text":"$y = 6x - 1$"},{"key":"B","text":"$y = 6x + 1$"},{"key":"C","text":"$y = \\frac{1}{6}x + \\frac{32}{3}$"},{"key":"D","text":"$y = -6x + 23$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $m = \\frac{29 - 11}{5 - 2} = \\frac{18}{3} = 6$. Using point-slope form with $(2, 11)$: $y - 11 = 6(x - 2)$, which simplifies to $y = 6x - 12 + 11 = 6x - 1$. The equation $y = 6x + 1$ results from a sign error when computing $-12 + 11$, incorrectly obtaining $+1$ instead of $-1$. The equation $y = \\frac{1}{6}x + \\frac{32}{3}$ reflects a concept gap, using the reciprocal of the slope instead of the slope itself. The equation $y = -6x + 23$ arises from an equation setup error, negating the slope when applying point-slope form.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20X8590', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $180$ shoppers at a mall and finds that $63\\%$ of them prefer contactless payment. A second researcher surveys a random sample of $720$ shoppers at the same mall and finds that $59\\%$ prefer contactless payment, with a smaller margin of error. Which of the following best explains why the second survey has a smaller margin of error?', NULL, $lyceon_json$[{"key":"A","text":"The second survey found a lower percentage, which reduces the margin of error."},{"key":"B","text":"The second survey used a larger sample size, which decreases the margin of error."},{"key":"C","text":"The second survey was conducted at a different time, which improves accuracy."},{"key":"D","text":"The second survey included shoppers who were more decisive about their preferences."}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error is inversely related to the square root of the sample size. The second survey sampled $720$ shoppers versus $180$, so its margin of error is smaller. The claim that a lower percentage reduces the margin of error conflates the value of the statistic with sampling precision — while the proportion does affect margin of error slightly, the dominant factor here is the fourfold increase in sample size. The suggestion about timing introduces an irrelevant factor that does not systematically affect margin of error. The claim about more decisive shoppers introduces an unsubstantiated assumption about respondent behavior that has no bearing on the statistical definition of margin of error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21NRPM0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $ABC$, the measure of angle $A$ is $53^\\circ$ and the measure of angle $B$ is $74^\\circ$. What is the measure, in degrees, of angle $C$?', NULL, $lyceon_json$[{"key":"A","text":"$43^\\circ$"},{"key":"B","text":"$53^\\circ$"},{"key":"C","text":"$107^\\circ$"},{"key":"D","text":"$127^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of any triangle is $180^\\circ$. Therefore, angle $C = 180^\\circ - 53^\\circ - 74^\\circ = 53^\\circ$. The value $43^\\circ$ results from a subtraction error such as computing $180 - 74 - 63$ instead of $180 - 74 - 53$. The value $107^\\circ$ comes from subtracting only angle $A$ from $180$ but then not subtracting angle $B$, reflecting incomplete reasoning. The value $127^\\circ$ results from subtracting only angle $A$ from $180$ ($180 - 53 = 127$) and treating that as the final answer, an equation setup error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21OGTSG', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'Which of the following points $(x, y)$ lies in the solution region of both $7x + 2y > 13$ and $-x + 3y \\leq -5$?', NULL, $lyceon_json$[{"key":"A","text":"$(1, 5)$"},{"key":"B","text":"$(6, 1)$"},{"key":"C","text":"$(3, -2)$"},{"key":"D","text":"$(-2, 3)$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $(3, -2)$: the first inequality gives $7(3) + 2(-2) = 21 - 4 = 17 > 13$, which is true, and the second gives $-(3) + 3(-2) = -3 - 6 = -9 \\leq -5$, which is also true. The point $(1, 5)$ satisfies the first inequality ($7(1) + 2(5) = 17 > 13$) but fails the second ($-(1) + 3(5) = 14 \\leq -5$ is false); choosing it reflects checking only the first inequality. The point $(6, 1)$ satisfies the first inequality ($7(6) + 2(1) = 44 > 13$) but fails the second ($-(6) + 3(1) = -3 \\leq -5$ is false); this error reflects mishandling the sign when evaluating the second inequality''s left side. The point $(-2, 3)$ fails the first inequality ($7(-2) + 2(3) = -8 > 13$ is false); choosing it reflects a concept gap about evaluating expressions with negative inputs.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM222I2DF', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{25x^2 - 81}{5x - 9}$ for $x \\neq \\frac{9}{5}$?', NULL, $lyceon_json$[{"key":"A","text":"$5x - 9$"},{"key":"B","text":"$25x + 9$"},{"key":"C","text":"$5x + 9$"},{"key":"D","text":"$5x^2 + 9$"}]$lyceon_json$::jsonb, 'C', NULL, E'The numerator $25x^2 - 81$ is a difference of squares: $(5x)^2 - 9^2 = (5x + 9)(5x - 9)$. Dividing by $(5x - 9)$ yields $5x + 9$. The distractor $5x - 9$ results from canceling the denominator but selecting the wrong factor of the difference of squares. The distractor $25x + 9$ comes from failing to recognize that $25x^2 = (5x)^2$, treating the square root of $25x^2$ as $25x$ rather than $5x$. The distractor $5x^2 + 9$ arises from dividing each term of the numerator separately by $5$ instead of by the binomial $(5x - 9)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM228QRSA', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{6x^2 + 19x - 7}{2x + 7} = ax + b$ for all $x \\neq -\\frac{7}{2}$, what is the value of $a \\cdot b$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$-1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring the numerator: $6x^2 + 19x - 7$. We need two numbers whose product is $6 \\times (-7) = -42$ and whose sum is $19$. Those are $21$ and $-2$. Rewriting: $6x^2 + 21x - 2x - 7 = 3x(2x + 7) - 1(2x + 7) = (3x - 1)(2x + 7)$. Dividing by $(2x + 7)$ gives $3x - 1$, so $a = 3$ and $b = -1$, and $a \\cdot b = 3 \\times (-1) = -3$. The distractor $-1$ comes from identifying only $b = -1$ and treating it as the answer, ignoring the multiplication by $a$. The distractor $2$ results from computing $a + b = 3 + (-1) = 2$ instead of the requested product $a \\cdot b$. The distractor $3$ comes from a sign error that yields $b = 1$ instead of $b = -1$, giving $a \\cdot b = 3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22M98TR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A school district observes that students who eat breakfast in the school cafeteria have higher average test scores than students who skip breakfast. Participation in the breakfast program is voluntary. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Eating breakfast in the cafeteria causes higher test scores."},{"key":"B","text":"There is an association between eating breakfast in the cafeteria and higher test scores."},{"key":"C","text":"Students who skip breakfast should be required to eat in the cafeteria."},{"key":"D","text":"The study proves that nutrition improves cognitive performance."}]$lyceon_json$::jsonb, 'B', NULL, E'Because participation is voluntary, this is an observational study. Students self-selected into the breakfast program, so confounding variables may explain the difference (e.g., students with more parental support may be more likely both to eat breakfast and to score higher). The data establish an association but not causation. The causal claim that eating breakfast causes higher scores is unwarranted without random assignment to control for confounders. The recommendation to require students to eat in the cafeteria is a policy prescription not supported by observational evidence alone. The claim that the study proves nutrition improves cognitive performance overgeneralizes far beyond what this single observational finding can support.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23OMF5P', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $350$ residents in a town found that $41\\%$ prefer expanded library hours, with a margin of error of $4\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $41\\%$ of all town residents prefer expanded library hours."},{"key":"B","text":"Between $37\\%$ and $45\\%$ of the sampled residents prefer expanded library hours."},{"key":"C","text":"It is plausible that between $37\\%$ and $45\\%$ of all town residents prefer expanded library hours."},{"key":"D","text":"No more than $45\\%$ of all town residents prefer expanded library hours."}]$lyceon_json$::jsonb, 'C', NULL, E'The margin of error produces a confidence interval around the sample statistic: $41\\% \\pm 4\\%$, or $37\\%$ to $45\\%$. This means it is plausible that the true population proportion falls within this range. The claim that exactly $41\\%$ of all residents prefer expanded hours treats the sample statistic as the exact population parameter, ignoring sampling variability. The claim about the sampled residents misapplies the interval — the margin of error addresses the population parameter, not the sample (the sample result is already known precisely). The claim of no more than $45\\%$ captures only the upper bound and ignores that the interval is two-sided.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23QT50Q', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A shelf holds $13$ novels: $5$ are mystery novels and $8$ are science fiction novels. Two novels are removed one at a time without replacement. Given that the first novel removed is a science fiction novel, what is the probability that the second novel removed is a mystery novel?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{13}$"},{"key":"B","text":"$\\frac{5}{12}$"},{"key":"C","text":"$\\frac{7}{12}$"},{"key":"D","text":"$\\frac{8}{13}$"}]$lyceon_json$::jsonb, 'B', NULL, E'After one science fiction novel is removed, $12$ novels remain on the shelf: $5$ mystery and $7$ science fiction. The conditional probability that the second novel is a mystery novel is $\\frac{5}{12}$. The distractor $\\frac{5}{13}$ fails to reduce the total from $13$ to $12$ after the first draw, ignoring the without-replacement condition. The distractor $\\frac{7}{12}$ correctly reduces the total to $12$ but uses the remaining science fiction count ($7$) instead of the mystery count ($5$), answering the wrong question. The distractor $\\frac{8}{13}$ uses the original science fiction count and original total, computing the unconditional probability of picking a science fiction novel from the full shelf.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25I6MHD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A hospital randomly assigns $90$ patients recovering from knee surgery to two groups. One group performs a new physical therapy routine, and the other group follows the standard routine. After $8$ weeks, patients in the new routine group report significantly less pain on average. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new routine is effective for all knee surgery patients at every hospital."},{"key":"B","text":"Patients who choose the new routine are naturally more committed to recovery."},{"key":"C","text":"The new routine likely caused the reduction in reported pain among the patients in this experiment."},{"key":"D","text":"There is an association between the new routine and reduced pain, but causation cannot be established."}]$lyceon_json$::jsonb, 'C', NULL, E'Because patients were randomly assigned to groups, this is a randomized experiment. Random assignment controls for confounding variables such as motivation or injury severity, so a causal conclusion about the treatment effect is appropriate for the study population. The claim about all knee surgery patients at every hospital overgeneralizes beyond the study''s population. The claim about patients naturally being more committed contradicts the study design — random assignment means patients did not choose their group, so self-selection bias is not a factor. The claim that causation cannot be established applies to observational studies, not randomized experiments, and reflects incomplete understanding of when causal inference is warranted.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25XGUW3', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A florist has a budget of at most $\\$529$ for a wedding order. Each centerpiece costs $\\$37$ in flowers, and there is a one-time delivery fee of $\\$67$. What is the maximum number of centerpieces the florist can prepare within this budget?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$12$"},{"key":"C","text":"$14$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'B', NULL, E'The inequality is $37c + 67 \\leq 529$. Subtracting 67 from both sides gives $37c \\leq 462$, and dividing by 37 gives $c \\leq 12.486\\ldots$, so the maximum whole number of centerpieces is 12. The distractor 11 results from a subtraction error such as computing $529 - 67 = 460$ and then $460 / 37 \\approx 12.4$, rounding down incorrectly. The distractor 14 results from ignoring the delivery fee entirely and computing $529 / 37 \\approx 14.3$, rounding down to 14. The distractor 16 results from adding the delivery fee instead of subtracting it, yielding $(529 + 67) / 37 \\approx 16.1$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26S82FE', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of the constant $k$ does the system of equations below have infinitely many solutions?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2749EE7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $WXY$, side $WX$ is extended through $X$ to point $Z$. If the exterior angle $YXZ$ measures $(7k + 3)^\\circ$, angle $W$ measures $(4k - 5)^\\circ$, and angle $Y$ measures $(2k + 17)^\\circ$, what is the measure, in degrees, of angle $W$?', NULL, $lyceon_json$[{"key":"A","text":"$9^\\circ$"},{"key":"B","text":"$31^\\circ$"},{"key":"C","text":"$35^\\circ$"},{"key":"D","text":"$66^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the exterior angle theorem, the exterior angle at a vertex equals the sum of the two non-adjacent interior angles: $(7k + 3) = (4k - 5) + (2k + 17)$. Simplifying the right side: $6k + 12$. So $7k + 3 = 6k + 12$, giving $k = 9$. Angle $W = 4(9) - 5 = 31^\\circ$. The value $9^\\circ$ is the value of $k$ itself, not the angle, reflecting partial reasoning. The value $35^\\circ$ is angle $Y = 2(9) + 17 = 35^\\circ$, a misread of which angle the question asks for. The value $66^\\circ$ is the exterior angle $7(9) + 3 = 66^\\circ$, confusing the exterior angle with the requested interior angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27A2CG0', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of $y$ in the solution to the system of equations below?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27AASDQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'Researchers want to test whether a new type of insulation reduces home heating costs. They randomly select $70$ homes from a northern city and randomly assign $35$ homes to receive the new insulation and $35$ homes to keep their existing insulation. Over one winter, homes with the new insulation had significantly lower heating costs on average. A trade publication reports: "New insulation proven to cut heating costs for homeowners nationwide." Which of the following best evaluates the publication''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is supported because the study used random assignment to treatment groups."},{"key":"B","text":"The claim is supported because the result was statistically significant."},{"key":"C","text":"The claim overgeneralizes because the homes were all in one northern city, so results may not apply to all climates and housing types nationwide."},{"key":"D","text":"The claim is invalid because the study should have used a survey to collect homeowner opinions instead."}]$lyceon_json$::jsonb, 'C', NULL, E'Although random assignment supports a causal conclusion within this study, all homes were drawn from a single northern city. Climate, housing construction, and energy costs vary widely across the country, so the results cannot be generalized to homeowners nationwide. The publication''s use of "nationwide" overgeneralizes beyond the study''s scope. Citing random assignment alone or statistical significance alone as justification ignores the limitation on generalizability — both support internal validity but do not address external validity. Suggesting a survey instead of an experiment reflects a fundamental misunderstanding of study design: surveys measure opinions or characteristics, while experiments with random assignment are required to test causal effects of interventions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27B9SDM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A cyclist rides the first 51 kilometers of a course at an average speed of 17 kilometers per hour and the remaining 39 kilometers at an average speed of 13 kilometers per hour. Which of the following is closest to the cyclist''s average speed, in kilometers per hour, for the entire course?', NULL, $lyceon_json$[{"key":"A","text":"14.5"},{"key":"B","text":"15"},{"key":"C","text":"15.5"},{"key":"D","text":"16"}]$lyceon_json$::jsonb, 'B', NULL, E'Time for the first segment: $\\frac{51}{17} = 3$ hours. Time for the second segment: $\\frac{39}{13} = 3$ hours. Total distance: $51 + 39 = 90$ km. Total time: $3 + 3 = 6$ hours. Average speed: $\\frac{90}{6} = 15$ km/h. The value 14.5 results from an arithmetic slip in computing the total distance or total time. The value 15.5 comes from a weighted-average approach that incorrectly weights the speeds by distance rather than by time, yielding a result between 15 and the simple average. The value 16 results from taking the simple average of the two speeds, $\\frac{17 + 13}{2} = 15$, and then rounding up or miscalculating.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27QI6NS', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A gym charges a one-time registration fee of $\\$47$ and a monthly membership fee of $\\$31$. Which function $f(m)$ gives the total cost, in dollars, after $m$ months of membership?', NULL, $lyceon_json$[{"key":"A","text":"$f(m) = 31m + 47$"},{"key":"B","text":"$f(m) = 47m + 31$"},{"key":"C","text":"$f(m) = 78m$"},{"key":"D","text":"$f(m) = 31m - 47$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the fixed registration fee plus the monthly fee times the number of months: $f(m) = 31m + 47$. The function $f(m) = 47m + 31$ reflects a concept gap, swapping the roles of the one-time fee and the monthly rate. The function $f(m) = 78m$ comes from an equation setup error, adding the two values together as a single rate and treating the total as purely proportional. The function $f(m) = 31m - 47$ arises from a sign error, subtracting the registration fee instead of adding it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM280DFUQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'grid_in', E'A jacket originally priced at $\\$85$ is on sale for $20\\%$ off. What is the sale price, in dollars, of the jacket?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '68', ARRAY['68'], E'The discount is $0.20 \\times 85 = \\$17$. The sale price is $85 - 17 = \\$68$. A common error is reporting only the discount amount of $\\$17$ rather than subtracting it from the original price. Another error is subtracting 20 from 85 to get $\\$65$, treating the percentage as a dollar amount.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM281CX4N', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher collects data on the age (in years) and resting heart rate (in beats per minute) of 50 adults. The line of best fit is $h = -0.6a + 97$, where $h$ is the predicted resting heart rate and $a$ is the age. An adult aged 45 has an actual resting heart rate of 67 beats per minute. What is the residual for this observation?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$3$"},{"key":"C","text":"$70$"},{"key":"D","text":"$97$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted heart rate at age 45 is $h = -0.6(45) + 97 = -27 + 97 = 70$. The residual is the actual value minus the predicted value: $67 - 70 = -3$. The value 3 results from reversing the subtraction order, computing predicted minus actual instead of actual minus predicted. The value 70 is the predicted value itself, not the residual. The value 97 is the y-intercept of the model, which represents the predicted heart rate at age 0 and is not relevant to the residual calculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM284FSI7', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $4(3x - 11) + 7x$?', NULL, $lyceon_json$[{"key":"A","text":"$19x - 11$"},{"key":"B","text":"$12x - 44$"},{"key":"C","text":"$19x - 44$"},{"key":"D","text":"$19x + 44$"}]$lyceon_json$::jsonb, 'C', NULL, E'Distributing the $4$ gives $4(3x - 11) + 7x = 12x - 44 + 7x = 19x - 44$. The distractor $19x - 11$ results from correctly combining $12x + 7x = 19x$ but failing to distribute the $4$ to $-11$, leaving the constant as $-11$ instead of $-44$. The distractor $12x - 44$ correctly distributes but omits the $+7x$ term when combining like terms. The distractor $19x + 44$ applies a sign error when distributing, treating $4(-11)$ as $+44$ instead of $-44$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28SPWBW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'In a school election, candidate $P$ received $35\\%$ of the votes and candidate $Q$ received $25\\%$ of the votes. The remaining votes were split equally between two other candidates. If candidate $P$ received 280 votes, how many votes did each of the two other candidates receive?', NULL, $lyceon_json$[{"key":"A","text":"$200$"},{"key":"B","text":"$320$"},{"key":"C","text":"$160$"},{"key":"D","text":"$120$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since candidate $P$ received $35\\%$ of the votes and got 280 votes, the total number of votes is $280 \\div 0.35 = 800$. Candidate $Q$ received $25\\%$ of 800, which is 200 votes. The remaining percentage is $100\\% - 35\\% - 25\\% = 40\\%$, so $0.40 \\times 800 = 320$ votes were split equally between two candidates, giving each $320 \\div 2 = 160$ votes. The distractor 200 is the number of votes candidate $Q$ received, not one of the two other candidates. The distractor 320 results from computing the total remaining votes but forgetting to divide by 2. The distractor 120 results from an arithmetic slip such as computing $40\\%$ of 800 as 240 and dividing by 2.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2978DS3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between the number of hours a student studies and the score on a test. The line of best fit has a slope of 7. Which of the following is the best interpretation of this slope?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of studying, the predicted test score increases by 7 points."},{"key":"B","text":"A student who studies for 7 hours will score a perfect 100."},{"key":"C","text":"The test score is always 7 times the number of hours studied."},{"key":"D","text":"The minimum test score is 7 points."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of a line of best fit represents the predicted change in the dependent variable (test score) for each one-unit increase in the independent variable (hours studied). A slope of 7 means the predicted test score increases by 7 points for each additional hour studied. The claim about scoring a perfect 100 after 7 hours confuses the slope with a specific outcome, ignoring the y-intercept. The claim that the score is always 7 times the hours confuses the slope with a direct proportionality that ignores the y-intercept. The claim about a minimum score of 7 confuses the slope with the y-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29RDF84', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'grid_in', E'A line of best fit for a data set is given by $y = 2.3x + 11$. Using this model, what is the predicted value of $y$ when $x = 9$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '31.7', ARRAY['31.7'], E'Substituting $x = 9$: $y = 2.3(9) + 11 = 20.7 + 11 = 31.7$. A common error is computing $2.3 \\times 9$ as $20.7$ but then adding 1.1 instead of 11, getting 21.8. Another error is forgetting the y-intercept entirely and reporting only $2.3 \\times 9 = 20.7$.', NULL, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ACNXY7', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $9x - 23 = 40$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$9$"},{"key":"C","text":"$-7$"},{"key":"D","text":"$63$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding $23$ to both sides gives $9x = 63$. Dividing both sides by $9$ gives $x = 7$. The distractor $9$ results from dividing $63$ by $7$ instead of by $9$, confusing the coefficient with the solution. The distractor $-7$ applies a sign error when isolating $x$. The distractor $63$ stops after adding $23$ to $40$ without dividing by $9$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2APX0N5', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'If $h(x) = -2(x + 5)^2 + 18$, which of the following describes the range of $h(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$h(x) \\leq 18$"},{"key":"B","text":"$h(x) \\geq 18$"},{"key":"C","text":"$h(x) \\leq -5$"},{"key":"D","text":"$h(x) \\geq -5$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $h(x) = -2(x + 5)^2 + 18$ is in vertex form with $a = -2 < 0$, so the parabola opens downward and the vertex $(-5, 18)$ is the maximum. Therefore $h(x) \\leq 18$ for all $x$. The distractor $h(x) \\geq 18$ reverses the inequality, treating the vertex as a minimum instead of a maximum despite the negative leading coefficient. The distractor $h(x) \\leq -5$ confuses the $x$-coordinate of the vertex ($-5$) with a bound on the output values. The distractor $h(x) \\geq -5$ similarly uses the $x$-coordinate as a lower bound on the range instead of identifying the $y$-coordinate as the upper bound.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C39I6K', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In right triangle $MNP$ with the right angle at $P$, $\\cos(M) = \\frac{20}{29}$. If the area of triangle $MNP$ is $840$ square units, what is the length of the hypotenuse $MN$?', NULL, $lyceon_json$[{"key":"A","text":"$29$"},{"key":"B","text":"$40$"},{"key":"C","text":"$42$"},{"key":"D","text":"$58$"}]$lyceon_json$::jsonb, 'D', NULL, E'Since $\\cos(M) = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{MP}{MN} = \\frac{20}{29}$, let $MP = 20k$ and $MN = 29k$. By the Pythagorean theorem, $NP = \\sqrt{(29k)^2 - (20k)^2} = \\sqrt{841k^2 - 400k^2} = \\sqrt{441k^2} = 21k$. The area is $\\frac{1}{2} \\times MP \\times NP = \\frac{1}{2}(20k)(21k) = 210k^2 = 840$, so $k^2 = 4$ and $k = 2$. The hypotenuse is $MN = 29(2) = 58$. The value $29$ is the ratio for the hypotenuse before scaling by $k = 2$, a misread that ignores the area constraint. The value $40$ equals $20k = 40$, the length of side $MP$, reflecting partial reasoning that reports the wrong side. The value $42$ equals $21k = 42$, the length of side $NP$, an arithmetic slip of selecting the wrong side of the triangle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CZS1BE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A store increases the price of an item by $25\\%$. Later, the store offers a $25\\%$ discount on the new price. If the original price of the item was $\\$64$, what is the final price after both changes?', NULL, $lyceon_json$[{"key":"A","text":"\\$56"},{"key":"B","text":"\\$60"},{"key":"C","text":"\\$64"},{"key":"D","text":"\\$68"}]$lyceon_json$::jsonb, 'B', NULL, E'After a $25\\%$ increase, the price becomes $64 \\times 1.25 = \\$80$. After a $25\\%$ discount on $\\$80$, the price becomes $80 \\times 0.75 = \\$60$. The value $\\$56$ results from an arithmetic slip such as computing $80 \\times 0.70$ instead of $80 \\times 0.75$. The value $\\$64$ comes from the misconception that a $25\\%$ increase followed by a $25\\%$ decrease returns to the original price. The value $\\$68$ results from computing the discount on the original price rather than the increased price, yielding $64 - 0.25 \\times 16 = 64 + 16 - 12 = 68$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D96ET5', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A water tank initially contains 1,150 liters. A pump drains water at a constant rate of 23 liters per minute. After how many minutes will the tank contain exactly 391 liters?', NULL, $lyceon_json$[{"key":"A","text":"$33$"},{"key":"B","text":"$17$"},{"key":"C","text":"$50$"},{"key":"D","text":"$67$"}]$lyceon_json$::jsonb, 'A', NULL, E'The amount of water after $t$ minutes is $W(t) = 1{,}150 - 23t$. Setting $W(t) = 391$: $1{,}150 - 23t = 391$. Subtracting 1,150 from both sides gives $-23t = -759$, so $t = 33$. The value 17 arises from misreading the question and dividing 391 by 23 directly instead of first computing the amount drained. The value 50 comes from an equation setup error: computing $1{,}150 \\div 23 = 50$, which is the time to drain the entire tank, not to reach 391 liters. The value 67 results from partial reasoning, incorrectly combining intermediate values such as adding 50 and 17.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E0LJAJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A chemist mixes compound $X$ and compound $Y$ in the ratio $9:4$ by mass. If the chemist has 117 grams of compound $X$, how many grams of compound $Y$ are needed to maintain this ratio?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '52', ARRAY['52'], E'Using the ratio $\\frac{9}{4} = \\frac{117}{y}$, cross-multiplying gives $9y = 468$, so $y = 52$ grams. A common error is computing $\\frac{117}{9} \\times 9 = 117$ by accidentally multiplying by the wrong ratio component. Another error is dividing 117 by 4 to get 29.25, confusing which quantity corresponds to which part of the ratio.', NULL, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ECBB0Z', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = -4x + 53$. For what value of $x$ does $g(x) = 17$?', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$9$"},{"key":"C","text":"$-15$"},{"key":"D","text":"$\\frac{17}{4}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting $g(x) = 17$: $-4x + 53 = 17$. Subtracting 53 from both sides gives $-4x = -36$, and dividing by $-4$ yields $x = 9$. The value $-9$ results from a sign error, dividing $-36$ by $-4$ and incorrectly keeping the negative sign. The value $-15$ comes from an arithmetic slip: computing $17 - 53 = -60$ instead of $-36$ and then dividing by $4$. The value $\\frac{17}{4}$ arises from partial reasoning, setting $4x = 17$ and dividing, ignoring the constant 53 entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F6KK4D', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'In the $xy$-plane, a circle has center $(4, -3)$ and is tangent to the line $y = 2$. A point $P$ lies on the circle such that the $x$-coordinate of $P$ is $8$. What is the $y$-coordinate of $P$ that is closest to the line $y = 2$?', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$0$"},{"key":"D","text":"$2$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since the circle has center $(4, -3)$ and is tangent to the line $y = 2$, the radius equals the distance from the center to the tangent line: $r = |2 - (-3)| = 5$. The circle equation is $(x - 4)^2 + (y + 3)^2 = 25$. Substituting $x = 8$: $(8 - 4)^2 + (y + 3)^2 = 25$, so $16 + (y + 3)^2 = 25$, giving $(y + 3)^2 = 9$ and $y + 3 = \\pm 3$. Thus $y = 0$ or $y = -6$. The $y$-coordinate closest to $y = 2$ is $y = 0$. The value $-6$ is the other valid $y$-coordinate on the circle but is farther from the line $y = 2$, a sign error in selecting the correct root. The value $-3$ is the $y$-coordinate of the center, not a point on the circle at $x = 8$. The value $2$ is the tangent line itself; no point on the circle at $x = 8$ has $y = 2$, reflecting a concept gap about tangency.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FOHV60', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A triangular garden has a base of $19$ feet and a height of $14$ feet. What is the area of the garden, in square feet?', NULL, $lyceon_json$[{"key":"A","text":"$33$"},{"key":"B","text":"$66$"},{"key":"C","text":"$133$"},{"key":"D","text":"$266$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a triangle is $\\frac{1}{2} \\times \\text{base} \\times \\text{height} = \\frac{1}{2}(19)(14) = \\frac{266}{2} = 133$ square feet. The value $33$ comes from adding $19 + 14 = 33$, confusing addition with the area formula. The value $66$ results from computing the perimeter $2(19 + 14) = 66$, applying a perimeter formula instead of an area formula. The value $266$ comes from computing $19 \\times 14 = 266$ without the factor of $\\frac{1}{2}$, applying the rectangle area formula instead of the triangle area formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G5UY4D', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $p$ is defined by $p(x) = -x^3 + 5x^2 - 7$. Which of the following correctly describes the end behavior of $p(x)$?', NULL, $lyceon_json$[{"key":"A","text":"As $x \\to \\infty$, $p(x) \\to -\\infty$; as $x \\to -\\infty$, $p(x) \\to \\infty$"},{"key":"B","text":"As $x \\to \\infty$, $p(x) \\to \\infty$; as $x \\to -\\infty$, $p(x) \\to -\\infty$"},{"key":"C","text":"As $x \\to \\infty$, $p(x) \\to \\infty$; as $x \\to -\\infty$, $p(x) \\to \\infty$"},{"key":"D","text":"As $x \\to \\infty$, $p(x) \\to -7$; as $x \\to -\\infty$, $p(x) \\to -7$"}]$lyceon_json$::jsonb, 'A', NULL, E'The leading term of $p(x) = -x^3 + 5x^2 - 7$ is $-x^3$. For an odd-degree polynomial with a negative leading coefficient, as $x \\to \\infty$ the function goes to $-\\infty$, and as $x \\to -\\infty$ the function goes to $\\infty$. The distractor stating both directions go to $\\infty$ and $-\\infty$ respectively with opposite signs describes the end behavior of $+x^3$, ignoring the negative leading coefficient. The distractor stating both ends go to $\\infty$ describes even-degree positive-leading-coefficient behavior, a fundamental concept gap about odd versus even degree. The distractor stating both ends approach $-7$ treats the constant term as a horizontal asymptote, which does not apply to polynomial functions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GG9A0A', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg has length $20$ and the other leg has length $21$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$27$"},{"key":"B","text":"$29$"},{"key":"C","text":"$31$"},{"key":"D","text":"$41$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Pythagorean theorem, $c = \\sqrt{20^2 + 21^2} = \\sqrt{400 + 441} = \\sqrt{841} = 29$. The value $27$ results from an arithmetic slip in computing $400 + 441$ incorrectly, such as getting $729$. The value $31$ comes from another arithmetic slip, perhaps miscomputing the square root after an error in the sum. The value $41$ results from simply adding the legs $20 + 21 = 41$ instead of applying the Pythagorean theorem.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GYWK2W', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A bakery sells croissants for $d$ dollars each and muffins for $m$ dollars each. If 7 croissants and 4 muffins cost $\\$53$, and 3 croissants and 4 muffins cost $\\$33$, what is the cost, in dollars, of one muffin?', NULL, $lyceon_json$[{"key":"A","text":"$\\$5$"},{"key":"B","text":"$\\$3$"},{"key":"C","text":"$\\$4.50$"},{"key":"D","text":"$\\$20$"}]$lyceon_json$::jsonb, 'C', NULL, E'The system is $7d + 4m = 53$ and $3d + 4m = 33$. Subtracting the second from the first eliminates $m$: $4d = 20$, so $d = 5$. Substituting $d = 5$ into the second equation gives $15 + 4m = 33$, so $4m = 18$ and $m = 4.50$. One muffin costs $\\$4.50$. The distractor $\\$5$ is the price of one croissant, not one muffin, resulting from answering for the wrong item. The distractor $\\$3$ comes from an arithmetic slip such as computing $4m = 12$ instead of $4m = 18$. The distractor $\\$20$ comes from stopping at $4d = 20$ without dividing by the coefficient and confusing it with the muffin price.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I8OXZ7', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What is the value of $x$ in the equation $$\\frac{4x - 3}{7} - 2 = \\frac{x + 5}{3}\\;?$$', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{86}{5}$"},{"key":"B","text":"$\\frac{52}{5}$"},{"key":"C","text":"$\\frac{44}{5}$"},{"key":"D","text":"$\\frac{22}{5}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiplying every term by 21 (the LCD of 7 and 3) gives $3(4x - 3) - 42 = 7(x + 5)$. Expanding: $12x - 9 - 42 = 7x + 35$, so $12x - 51 = 7x + 35$. Subtracting $7x$ and adding 51 yields $5x = 86$, thus $x = \\frac{86}{5}$. The value $\\frac{52}{5}$ results from partial reasoning: failing to multiply the standalone $-2$ by the LCD produces $12x - 9 - 2 = 7x + 35$, giving $5x = 46$ and an additional miscalculation yields $\\frac{52}{5}$. The value $\\frac{44}{5}$ comes from a sign error: ignoring the $-2$ entirely and solving $\\frac{4x-3}{7} = \\frac{x+5}{3}$ gives $12x - 9 = 7x + 35$, so $5x = 44$. The value $\\frac{22}{5}$ comes from an equation setup error: cross-multiplying without the $-2$ term and miscalculating the constant as $12x - 9 = 7x + 13$, yielding $5x = 22$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IN5N8T', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the solution to the equation $5(2x + 7) = 3x - 14$?', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$3$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Distributing gives $10x + 35 = 3x - 14$. Subtracting $3x$ from both sides yields $7x + 35 = -14$. Subtracting 35 gives $7x = -49$, so $x = -7$. The value $-9$ results from an arithmetic slip, such as computing $-49 \\div 7$ incorrectly as $-9$. The value 3 comes from a sign error when subtracting 35, treating $-14 - 35$ as $-14 + 35 = 21$ and then solving $7x = 21$. The value 7 arises from partial reasoning, dropping the negative sign in the final step and reporting $49 \\div 7 = 7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J1HBNS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 + 10x - 18y + 81 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{81}$"},{"key":"B","text":"$5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'B', NULL, E'Completing the square: $(x^2 + 10x + 25) + (y^2 - 18y + 81) = -81 + 25 + 81$, which gives $(x + 5)^2 + (y - 9)^2 = 25$. The radius is $r = \\sqrt{25} = 5$. The value $\\sqrt{81} = 9$ comes from incorrectly treating the constant term $81$ as $r^2$, misreading the equation rather than completing the square. The value $7$ is an arithmetic slip from miscalculating the sum $-81 + 25 + 81$. The value $25$ gives $r^2$ rather than $r$, a concept gap about the final step of extracting the radius from standard form.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K6E8IQ', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $7x - 4y = 52$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -13)$"},{"key":"B","text":"$(0, -7)$"},{"key":"C","text":"$(0, 13)$"},{"key":"D","text":"$(\\frac{52}{7}, 0)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The $y$-intercept occurs where $x = 0$. Substituting gives $-4y = 52$, so $y = -13$, and the intercept is $(0, -13)$. The point $(0, -7)$ results from a concept gap, dividing 52 by the coefficient of $x$ (7) instead of the coefficient of $y$ (4) and misapplying a sign. The point $(0, 13)$ comes from a sign error, dropping the negative when dividing $52$ by $-4$. The point $(\\frac{52}{7}, 0)$ is the $x$-intercept, indicating the question was misread as asking for the $x$-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LTAN3U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A teacher records the following quiz scores for 9 students: 53, 61, 67, 71, 74, 78, 82, 89, 95. If the score of 53 is removed from the data set, which of the following correctly describes the change in the mean and the median?', NULL, $lyceon_json$[{"key":"A","text":"Both the mean and the median increase."},{"key":"B","text":"The mean increases and the median stays the same."},{"key":"C","text":"The mean stays the same and the median increases."},{"key":"D","text":"The mean increases and the median decreases."}]$lyceon_json$::jsonb, 'A', NULL, E'Original 9 scores sum to $53 + 61 + 67 + 71 + 74 + 78 + 82 + 89 + 95 = 670$. Original mean: $\\frac{670}{9} \\approx 74.4$. Original median (5th value): 74. After removing 53, the 8 remaining scores sum to 617. New mean: $\\frac{617}{8} \\approx 77.1$, which is higher. New median is the average of the 4th and 5th values: $\\frac{74 + 78}{2} = 76$, which is also higher than 74. So both increase. The claim that the mean increases but the median stays the same is wrong because the median shifts from the 5th to the average of the 4th and 5th positions. The claim that the mean stays the same ignores that the removed value is below the original mean. The claim that the median decreases is wrong because the middle values shift upward when the lowest value is removed.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M897OL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle $GHK$ with the right angle at $K$, $\\tan(G) = \\frac{11}{60}$. What is $\\cos(G)$? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60/61', ARRAY['60/61', '0.983', '.983', '0.984', '.984'], E'Since $\\tan(G) = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{11}{60}$, the side opposite angle $G$ (which is $HK$) has length $11$ and the side adjacent to angle $G$ (which is $GK$) has length $60$. By the Pythagorean theorem, the hypotenuse $GH = \\sqrt{11^2 + 60^2} = \\sqrt{121 + 3600} = \\sqrt{3721} = 61$. Therefore $\\cos(G) = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{60}{61}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MD41KD', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f(x) = (x - 7)^2 + 3$ has a minimum value. What is this minimum value?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$7$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $f(x) = (x - 7)^2 + 3$ is in vertex form $f(x) = a(x - h)^2 + k$ with $a = 1 > 0$, so the parabola opens upward and the vertex $(7, 3)$ is the minimum. The minimum value of $f(x)$ is $3$. The distractor $7$ confuses the $x$-coordinate of the vertex with the minimum output value. The distractor $-3$ results from a sign error, negating the constant $+3$. The distractor $10$ comes from adding $7 + 3$ as though the minimum were the sum of the vertex coordinates.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NWCCSL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling firm surveys a random sample of $500$ registered voters in a district and finds that $48\\%$ support Measure J and $52\\%$ oppose it, each with a margin of error of $4\\%$. A newspaper headline reads: "Voters reject Measure J." Which of the following best evaluates the newspaper''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is justified because $52\\%$ opposing is greater than $48\\%$ supporting."},{"key":"B","text":"The claim is justified because the sample size of $500$ is large enough to eliminate all uncertainty."},{"key":"C","text":"The claim is not justified because the confidence intervals for support and opposition overlap."},{"key":"D","text":"The claim is not justified because the poll only surveyed registered voters, not all residents."}]$lyceon_json$::jsonb, 'C', NULL, E'The confidence interval for support is $44\\%$ to $52\\%$, and for opposition is $48\\%$ to $56\\%$. Because these intervals overlap (both include values between $48\\%$ and $52\\%$), the difference between support and opposition is within the margin of error, so the data do not clearly establish that a majority opposes the measure. The claim based solely on $52\\% > 48\\%$ uses partial reasoning — it ignores that the observed difference ($4$ percentage points) does not exceed twice the margin of error ($8$ percentage points). The assertion that $500$ respondents eliminate all uncertainty reflects a conceptual gap — no finite sample eliminates sampling error entirely. The objection about surveying only registered voters misidentifies the relevant population — for a ballot measure, registered voters are the appropriate population to survey.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O6VZR4', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A rectangular fish pond is $13$ feet long and $7$ feet wide. A uniform stone walkway of width $2$ feet surrounds the pond on all sides. What is the area, in square feet, of the walkway alone?', NULL, $lyceon_json$[{"key":"A","text":"$91$"},{"key":"B","text":"$96$"},{"key":"C","text":"$187$"},{"key":"D","text":"$104$"}]$lyceon_json$::jsonb, 'B', NULL, E'The outer rectangle, including the walkway, has length $13 + 2(2) = 17$ feet and width $7 + 2(2) = 11$ feet, giving an outer area of $17 \\times 11 = 187$ square feet. The pond area is $13 \\times 7 = 91$ square feet. The walkway area is $187 - 91 = 96$ square feet. The value $91$ is the area of the pond itself, not the walkway, a misread of what the question asks. The value $187$ is the total outer area without subtracting the pond, reflecting partial reasoning that stops before the final step. The value $104$ results from an arithmetic slip such as adding $2$ to each dimension only once (computing $15 \\times 9 = 135$, then $135 - 91 = 44$) or another miscalculation in the outer dimensions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OGD7VG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A printer uses 17 milliliters of ink to print 4 pages. At this rate, how many milliliters of ink are needed to print 28 pages?', NULL, $lyceon_json$[{"key":"A","text":"112"},{"key":"B","text":"119"},{"key":"C","text":"121"},{"key":"D","text":"136"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{17}{4}$ milliliters per page. For 28 pages: $\\frac{17}{4} \\times 28 = 17 \\times 7 = 119$ milliliters. The value 112 results from an arithmetic slip such as computing $16 \\times 7$. The value 121 comes from setting up the proportion incorrectly, for example computing $\\frac{17 \\times 28}{4}$ with a rounding error. The value 136 arises from multiplying $17 \\times 8$ instead of recognizing that $28 \\div 4 = 7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P7GVZI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $34$ units. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$17\\pi$"},{"key":"B","text":"$34\\pi$"},{"key":"C","text":"$289\\pi$"},{"key":"D","text":"$1156\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The radius is half the diameter: $r = 34 / 2 = 17$. The area is $A = \\pi r^2 = \\pi(17)^2 = 289\\pi$. The value $17\\pi$ results from computing $\\pi r$ instead of $\\pi r^2$, omitting the squaring. The value $34\\pi$ comes from using the diameter in the circumference formula $\\pi d$ or confusing circumference with area. The value $1156\\pi$ uses the diameter instead of the radius in the area formula: $\\pi(34)^2 = 1156\\pi$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PMNOD6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'At a veterinary clinic, $150$ pets were examined last month. Of these, $54$ were cats and $96$ were dogs. Among the cats, $21$ received flea treatments, and among the dogs, $37$ received flea treatments. If a pet is selected at random from those that received flea treatments, what is the probability that it is a cat?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{21}{54}$"},{"key":"B","text":"$\\frac{21}{150}$"},{"key":"C","text":"$\\frac{21}{58}$"},{"key":"D","text":"$\\frac{37}{58}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The condition restricts the sample space to pets that received flea treatments: $21 + 37 = 58$ total treated pets. Of these, $21$ are cats, so the conditional probability is $\\frac{21}{58}$. The distractor $\\frac{21}{54}$ incorrectly uses the total number of cats as the denominator rather than the total number of treated pets, setting up the conditional probability with the wrong sample space. The distractor $\\frac{21}{150}$ uses the entire clinic population as the denominator, computing the unconditional probability of selecting a treated cat rather than the conditional probability given flea treatment. The distractor $\\frac{37}{58}$ correctly identifies the treated-pet total but uses the number of treated dogs in the numerator, answering which pet is a dog rather than a cat.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RNAK19', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'The six values in a data set are 11, 15, 18, 23, 29, and $k$, where $k$ is a positive integer. If the mean of the data set is 19, what is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '18', ARRAY['18'], E'The mean of the six values is $\\frac{11 + 15 + 18 + 23 + 29 + k}{6} = 19$. Simplifying: $\\frac{96 + k}{6} = 19$, so $96 + k = 114$, giving $k = 18$. A common error is computing the sum of the known values incorrectly, such as getting 94 instead of 96, yielding $k = 20$. Another error is dividing by 5 instead of 6, forgetting to include $k$ in the count.', NULL, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S8CMZH', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $7x^2 - 39x + 20 = 0$, what is the smaller value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4/7', ARRAY['4/7', '0.571', '.571'], E'Using the quadratic formula: $x = \\frac{39 \\pm \\sqrt{(-39)^2 - 4(7)(20)}}{2(7)} = \\frac{39 \\pm \\sqrt{1521 - 560}}{14} = \\frac{39 \\pm \\sqrt{961}}{14} = \\frac{39 \\pm 31}{14}$. This gives $x = \\frac{70}{14} = 5$ or $x = \\frac{8}{14} = \\frac{4}{7}$. The smaller value is $\\frac{4}{7}$. This can be verified by factoring: $7x^2 - 39x + 20 = (7x - 4)(x - 5) = 7x^2 - 35x - 4x + 20 = 7x^2 - 39x + 20$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SI5D3Z', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A community theater group has $7$ actors, $11$ stagehands, and $3$ lighting technicians. If one member is selected at random to lead the next meeting, what is the probability that the selected member is a stagehand?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{21}$"},{"key":"B","text":"$\\frac{11}{21}$"},{"key":"C","text":"$\\frac{11}{10}$"},{"key":"D","text":"$\\frac{3}{21}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of members is $7 + 11 + 3 = 21$. The probability of selecting a stagehand is $\\frac{11}{21}$. The distractor $\\frac{7}{21}$ uses the count of actors instead of stagehands, misreading which role the question asks about. The distractor $\\frac{11}{10}$ divides the stagehand count by the number of non-stagehand members ($7 + 3 = 10$) rather than the total, setting up the fraction incorrectly. The distractor $\\frac{3}{21}$ uses the count of lighting technicians instead of stagehands.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T2OS4J', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cylindrical storage container has a diameter of $6$ meters and a height of $11$ meters. The volume of the container can be written as $k\\pi$ cubic meters. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '99', ARRAY['99'], E'The radius is half the diameter: $r = 6/2 = 3$ meters. The volume of a cylinder is $V = \\pi r^2 h = \\pi(3)^2(11) = \\pi(9)(11) = 99\\pi$ cubic meters. Therefore $k = 99$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TMISKB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set consists of the values 14, 19, 22, 22, 28. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"19"},{"key":"B","text":"21"},{"key":"C","text":"22"},{"key":"D","text":"25"}]$lyceon_json$::jsonb, 'C', NULL, E'The data set has 5 values already in order: 14, 19, 22, 22, 28. The median is the middle (third) value, which is 22. The value 19 results from selecting the second value instead of the third, confusing the position of the median. The value 21 comes from averaging the second and third values ($\\frac{19 + 22}{2} = 20.5$, rounded to 21), a method applicable to even-count data sets, not odd. The value 25 comes from averaging the fourth and fifth values or misidentifying the middle position.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X4NJEJ', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $\\ell$ is perpendicular to the line $5x - 3y = 21$ and passes through the point $(10, -4)$. What is the $y$-intercept of line $\\ell$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, 2)$"},{"key":"B","text":"$(0, -10)$"},{"key":"C","text":"$(0, \\frac{26}{5})$"},{"key":"D","text":"$(0, \\frac{46}{3})$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, solve for the slope of $5x - 3y = 21$: rearranging gives $y = \\frac{5}{3}x - 7$, so the slope is $\\frac{5}{3}$. The perpendicular slope is $-\\frac{3}{5}$. Using point-slope form with $(10, -4)$: $y + 4 = -\\frac{3}{5}(x - 10)$, so $y + 4 = -\\frac{3}{5}x + 6$, giving $y = -\\frac{3}{5}x + 2$. The $y$-intercept is $(0, 2)$. The intercept $(0, -10)$ results from a sign error, using slope $\\frac{3}{5}$ instead of $-\\frac{3}{5}$, which gives $y = \\frac{3}{5}x - 10$. The intercept $(0, \\frac{26}{5})$ reflects a concept gap: using the original slope $\\frac{5}{3}$ rather than its negative reciprocal and miscalculating the constant. The intercept $(0, \\frac{46}{3})$ comes from an equation setup error, using the reciprocal $\\frac{3}{5}$ without negating and arriving at an incorrect constant.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XXUNOA', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the sum of the solutions to the equation $x^2 - 11x + 24 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$24$"},{"key":"C","text":"$-11$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring gives $x^2 - 11x + 24 = (x - 3)(x - 8) = 0$, so $x = 3$ or $x = 8$. The sum of the solutions is $3 + 8 = 11$. By Vieta''s formulas, the sum of the roots of $x^2 + bx + c = 0$ equals $-b$, which is $-(-11) = 11$. The distractor $24$ confuses the sum of the roots with the product of the roots. The distractor $-11$ applies a sign error, taking the coefficient of $x$ directly instead of negating it. The distractor $5$ results from computing $8 - 3 = 5$ (the difference rather than the sum).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YHYXMN', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the system $y = 3x^2 - 7x + k$ and $y = 5x - 9$ have exactly one real solution?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$3$"},{"key":"C","text":"$9$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the equations equal: $3x^2 - 7x + k = 5x - 9$, which simplifies to $3x^2 - 12x + (k + 9) = 0$. For exactly one real solution, the discriminant must equal zero: $(-12)^2 - 4(3)(k + 9) = 0$, so $144 - 12(k + 9) = 0$, giving $144 - 12k - 108 = 0$, thus $36 = 12k$ and $k = 3$. The distractor $-3$ results from a sign error when moving the constant $9$ to the other side, yielding $(k - 9)$ instead of $(k + 9)$. The distractor $9$ comes from an arithmetic slip such as forgetting to distribute the $-12$ to $9$, effectively solving $144 = 12k + 36$ incorrectly. The distractor $12$ arises from dividing the discriminant $144$ by $12$ without subtracting $108$ first, confusing the discriminant condition with a simpler equation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YNKZP3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. One of the alternate interior angles measures $(3x + 11)^\\circ$ and the other measures $(5x - 17)^\\circ$. What is the measure, in degrees, of each of these alternate interior angles?', NULL, $lyceon_json$[{"key":"A","text":"$14^\\circ$"},{"key":"B","text":"$28^\\circ$"},{"key":"C","text":"$53^\\circ$"},{"key":"D","text":"$127^\\circ$"}]$lyceon_json$::jsonb, 'C', NULL, E'Alternate interior angles formed by parallel lines and a transversal are equal: $3x + 11 = 5x - 17$. Solving gives $28 = 2x$, so $x = 14$. Substituting back: $3(14) + 11 = 42 + 11 = 53^\\circ$. The value $14^\\circ$ is the value of $x$ itself, not the angle measure, reflecting partial reasoning that stops too early. The value $28^\\circ$ comes from computing $2x = 28$ and stopping, an arithmetic slip in tracking the solution. The value $127^\\circ$ results from computing $180 - 53 = 127$, treating the angles as supplementary rather than equal, a concept gap about alternate interior angles.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YRBTEV', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of $x$ satisfies the inequality $7x - 19 > 30$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$8$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding 19 to both sides gives $7x > 49$, and dividing by 7 gives $x > 7$. Among the choices, only $8$ is strictly greater than 7, since $7(8) - 19 = 37 > 30$. The value $7$ yields $7(7) - 19 = 30$, which equals 30 but is not strictly greater than 30, reflecting confusion between $>$ and $\\geq$. The value $5$ gives $7(5) - 19 = 16$, which does not exceed 30; this could result from an arithmetic slip in solving. The value $3$ gives $7(3) - 19 = 2$, which clearly fails the inequality and reflects a general concept gap about what the inequality requires.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23CY9DN', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The coalition of urban planners that reviews zoning proposals for the city of Savannah _____ its quarterly report last Tuesday, recommending increased green-space requirements for all new commercial developments.', $lyceon_json$[{"key":"A","text":"release"},{"key":"B","text":"releases"},{"key":"C","text":"have released"},{"key":"D","text":"released"}]$lyceon_json$::jsonb, 'D', NULL, E'The time marker "last Tuesday" establishes a past-tense context, so the verb must be in the simple past. The singular subject "coalition" requires agreement with a singular verb, and "released" is the correct simple past form. The bare plural present-tense form "release" fails to agree with the singular subject and is in the wrong tense. The third-person singular present "releases" agrees in number but is in the wrong tense for a completed past action. The plural present perfect "have released" fails on number agreement with the singular "coalition" and introduces an inappropriate tense for an event tied to a specific past date.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23RSLFP', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Each of the fourteen doctoral candidates who presented findings at the symposium on cellular senescence _____ required to submit a revised manuscript incorporating feedback from at least two independent reviewers before the proceedings could be finalized.', $lyceon_json$[{"key":"A","text":"were"},{"key":"B","text":"are"},{"key":"C","text":"was"},{"key":"D","text":"have been"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the sentence is "Each," which is singular regardless of the prepositional phrase "of the fourteen doctoral candidates" that follows it. The sentence also establishes a past-tense context with "presented" and "could be finalized," requiring a past-tense verb. The singular past-tense "was" correctly agrees with "Each" and maintains tense consistency. The plural past-tense "were" incorrectly matches the nearer noun "candidates" rather than the true subject "Each." The plural present-tense "are" fails on both number agreement and tense. The plural present-perfect "have been" also fails on number agreement with "Each" and shifts the tense away from the established past-tense frame.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26IXAG3', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Cognitive scientist Yumi Takahashi conducted experiments in which 203 bilingual Japanese-English speakers were asked to estimate the duration of animated events shown on a screen. When tested in Japanese, participants consistently estimated event durations as shorter than participants tested in English, even when viewing identical animations. Takahashi noted that the Japanese language more frequently encodes events using grammatical constructions that emphasize completion — verb endings that mark an action as finished — whereas English more often uses progressive constructions that frame actions as ongoing. She argued that these grammatical differences do not merely reflect different ways of describing events but actively shape temporal cognition, leading her to conclude that ________', $lyceon_json$[{"key":"A","text":"speakers of languages that grammatically emphasize event completion may systematically perceive events as occupying less time than speakers of languages that emphasize event continuation."},{"key":"B","text":"bilingual individuals always estimate event durations more accurately in their first language than in their second language."},{"key":"C","text":"Japanese grammatical constructions are inherently more efficient than English constructions for describing timed events."},{"key":"D","text":"temporal estimation accuracy improves significantly when participants are tested in a language they learned after age twelve."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a study in which language of testing influenced temporal estimates: Japanese (with completion-oriented grammar) led to shorter duration estimates than English (with continuation-oriented grammar). Takahashi argued that grammar actively shapes temporal cognition, so the logical conclusion is that languages emphasizing completion cause speakers to perceive events as shorter. The option about bilingual individuals being more accurate in their first language introduces a claim about accuracy and language order that the passage does not address — the study compared languages, not proficiency levels. The option about Japanese being inherently more efficient mischaracterizes the finding as one about linguistic efficiency rather than about how grammar shapes perception. The option about age of acquisition and estimation accuracy introduces a variable the passage never mentions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26KFG2R', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the passage?', E'In 2019, marine biologist Solange Rakotoarisoa identified a previously undocumented species of seahorse living among the mangrove roots of a lagoon in northeastern Madagascar. The species, measuring only nine millimeters in length, was so small that it had been overlooked by earlier surveys of the lagoon''s fauna conducted in 2004 and 2011.', $lyceon_json$[{"key":"A","text":"To report a biological discovery and explain why it went undetected"},{"key":"B","text":"To argue that earlier surveys of the lagoon were poorly designed"},{"key":"C","text":"To compare the biodiversity of mangrove ecosystems across multiple regions"},{"key":"D","text":"To outline the methods marine biologists use to classify new species"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage announces Rakotoarisoa''s discovery of a new seahorse species and attributes its previous detection failure to the animal''s extremely small size. Its function is to report a discovery and explain why it was missed. Arguing that earlier surveys were poorly designed overstates the passage''s claim — it notes the seahorse was overlooked due to its size, not that the surveys themselves were flawed in methodology. Comparing biodiversity across regions is not addressed; only one lagoon in Madagascar is discussed. Outlining classification methods misidentifies the passage''s purpose; no procedures for taxonomic classification are described.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26Y246R', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the passage, "arrested" most nearly means', E'The sudden appearance of a barn owl gliding silently across the meadow arrested the birdwatchers'' attention. For nearly a full minute, the group stood motionless, binoculars raised, forgetting the sandhill cranes they had originally come to observe.', $lyceon_json$[{"key":"A","text":"detained by police"},{"key":"B","text":"captured"},{"key":"C","text":"delayed"},{"key":"D","text":"released"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes the birdwatchers becoming completely absorbed by the barn owl, standing motionless and forgetting their original purpose. "Captured" correctly conveys the sense of seizing or taking hold of someone''s focus. "Detained by police" refers to a law enforcement action involving physical custody, which is incoherent when applied to a group voluntarily watching an owl. "Delayed" means to cause something to happen later than expected, but the passage describes attention being seized, not a schedule being postponed. "Released" means to set free, which is the opposite of what the passage describes — the birdwatchers'' attention was held fast, not let go.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28Q9NTV', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Economist Yael Mizrahi has demonstrated that municipalities that adopted participatory budgeting between 2008 and 2016 saw, on average, a 14% increase in infrastructure spending directed toward low-income neighborhoods. Skeptics have cautioned that this correlation may reflect self-selection: cities already committed to equity-oriented policies were more likely to adopt participatory budgeting in the first place, meaning the budgeting mechanism itself may not have caused the spending shift. Mizrahi acknowledges the self-selection concern but argues that her difference-in-differences analysis, which compares pre- and post-adoption spending trajectories in adopting cities against matched non-adopting cities, substantially controls for preexisting policy orientation. _______ she notes that even among the subset of cities that adopted participatory budgeting under state mandates -- eliminating voluntary self-selection entirely -- the infrastructure spending shift toward low-income areas remained statistically significant at the 0.01 level.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"Conversely,"},{"key":"C","text":"Notwithstanding,"},{"key":"D","text":"For example,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence before the blank presents Mizrahi''s first defense against the self-selection criticism -- her difference-in-differences analysis controls for preexisting policy orientation. The sentence after the blank presents an additional, reinforcing piece of evidence: even cities that adopted participatory budgeting involuntarily (under state mandates) showed the same spending shift. "Moreover," correctly signals that Mizrahi is layering a second, complementary argument on top of the first to further strengthen her case against the self-selection objection. "Conversely," implies the mandate-based finding contradicts the difference-in-differences analysis, but the two pieces of evidence point in the same direction and reinforce each other. "Notwithstanding," introduces a fact that persists despite an obstacle, but the mandate finding is not overcoming the difference-in-differences analysis; it is building on it. "For example," would introduce a specific instance of the general claim made in the preceding sentence, but the mandate-based analysis is a separate methodological approach, not an illustration of the difference-in-differences technique.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29SZ8OX', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the study, if accurate, would most directly undermine the researchers'' conclusion?', E'A 2023 study of 114 sixteenth-century Portuguese nautical charts concluded that the systematic westward displacement of the African coastline visible in charts produced after 1502 was a deliberate cartographic strategy rather than an accumulation of navigational errors. The researchers argued that Portuguese chartmakers, under instructions from the crown, intentionally shifted the coastline to make the demarcation line established by the Treaty of Tordesillas appear to encompass more of the South American landmass within Portugal''s territorial claim. The study supported this argument by noting that the displacement appeared abruptly and uniformly across charts from multiple workshops, a pattern inconsistent with gradual error accumulation.', $lyceon_json$[{"key":"A","text":"Charts produced by Spanish cartographers during the same period display a comparable westward shift in the African coastline, despite Spain having no incentive to enlarge Portugal's territorial claim."},{"key":"B","text":"Portuguese crown records from the early 1500s include correspondence discussing the strategic importance of the Tordesillas demarcation line."},{"key":"C","text":"Navigational instruments available to Portuguese sailors in the early sixteenth century were less accurate for longitude measurements than for latitude measurements."},{"key":"D","text":"Several charts produced before 1502 by the same workshops show minor, inconsistent westward displacements attributable to copying errors."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers'' conclusion rests on the claim that Portuguese chartmakers deliberately shifted the African coastline to benefit Portugal''s territorial claim under the Treaty of Tordesillas. If Spanish cartographers — who had no reason to enlarge Portugal''s claim — independently produced the same displacement, the shift cannot be explained by deliberate Portuguese strategy and more likely reflects a common technical or methodological factor, directly undermining the conclusion. The finding about Portuguese crown correspondence discussing the Tordesillas line would strengthen rather than undermine the conclusion by showing official interest in the boundary. The finding about longitude inaccuracy addresses general navigational limitations but does not explain the abrupt and uniform appearance of the displacement that the study identified. The finding about pre-1502 copying errors shows minor inconsistencies before the critical date but does not challenge the post-1502 pattern that forms the study''s primary evidence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A0XNA8', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes how Ibanez''s findings relate to Moretti''s theoretical claim?', E'Text 1
