INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B4WP3J', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the passages, how would Vasquez most likely respond to Chen''s recommendation?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BRAGHO', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The painted bunting (Passerina ciris) is among the most vividly colored songbirds in North America, with males displaying bright blue, green, and red plumage. Despite this conspicuous appearance, painted buntings are remarkably difficult to observe in the wild. Field researchers conducting breeding surveys in coastal South Carolina between 2018 and 2023 reported that they detected 83% of territorial males by song alone, without ever achieving a visual sighting. This finding suggests that ________', $lyceon_json$[{"key":"A","text":"painted buntings tend to sing and forage within dense vegetation that conceals them despite their vivid coloration."},{"key":"B","text":"the bright plumage of male painted buntings is primarily useful for attracting mates during nighttime displays."},{"key":"C","text":"female painted buntings are easier to observe in the field than males because their plumage is less conspicuous."},{"key":"D","text":"territorial male painted buntings sing less frequently during the breeding season than during migration."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage notes that despite vivid coloring, most males were detected by sound rather than sight. The most logical explanation is that the birds inhabit dense cover that hides them visually, reconciling their bright plumage with their low visual detection rate. The option about nighttime displays introduces an unsupported claim — the passage provides no information about when displays occur, and nighttime activity would not explain daytime detection by song. The option about females being easier to observe introduces a comparison not addressed in the passage, and less conspicuous plumage would logically make females harder, not easier, to spot. The option about reduced singing during breeding contradicts the passage''s implication that song is the primary detection method during breeding surveys.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D6Z29H', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a recommendation to a city council and wants to argue that a proposed initiative would address two distinct community needs simultaneously. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E4V85J', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Computational linguist Sonja Ehrhardt developed a parsing algorithm that can identify syntactic anomalies in medieval Icelandic _____ a capability that has allowed historians to attribute several disputed manuscripts to a single anonymous scribe working in the late thirteenth century.', $lyceon_json$[{"key":"A","text":"Icelandic,"},{"key":"B","text":"Icelandic;"},{"key":"C","text":"Icelandic:"},{"key":"D","text":"Icelandic"}]$lyceon_json$::jsonb, 'A', NULL, E'The phrase "a capability that has allowed historians to attribute several disputed manuscripts to a single anonymous scribe" is a nonrestrictive appositive renaming the entire preceding idea. In Standard English, a nonrestrictive appositive is introduced by a comma. A semicolon after "Icelandic" would incorrectly signal the start of a new independent clause, but the appositive phrase beginning with "a capability" is not an independent clause — it lacks a main verb predicate of its own. A colon after "Icelandic" would incorrectly signal that a list or formal elaboration follows; while the appositive does elaborate, a colon is not standard before a noun-phrase appositive introduced without a complete clause on the right side. Omitting punctuation entirely after "Icelandic" fuses the appositive into the preceding clause without the required pause, making it appear that "Icelandic a capability" is a continuous noun phrase.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EQO0I4', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Computational linguist Hana Dvorakova has developed an algorithm that identifies syntactic patterns unique to individual authors, enabling attribution of anonymous medieval manuscripts to known scribes. When tested on a corpus of 134 authenticated Czech manuscripts from the fourteenth century, the algorithm correctly attributed 89% of the texts. _______ when Dvorakova applied the same algorithm to a set of disputed Provencal texts from the same period, the accuracy dropped to 53%, a rate barely above chance, suggesting that the syntactic markers the algorithm relies on may be language-specific rather than universal.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"However,"},{"key":"C","text":"In other words,"},{"key":"D","text":"As a result,"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence before the blank describes the algorithm''s strong performance on Czech manuscripts (89% accuracy), and the sentence after the blank describes its much weaker performance on Provencal texts (53% accuracy). "However," correctly signals this contrast between the two results. "In addition," implies that the Provencal result is a parallel or supplementary finding, but the drop from 89% to 53% represents a complication, not a simple addition to the prior success. "In other words," would restate the previous claim in different terms, but the Provencal finding introduces new, different information rather than rephrasing the Czech result. "As a result," implies the poor Provencal performance was caused by the Czech success, but the two tests are independent applications of the same algorithm.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GB1FED', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Musicologist Farah Nassiri-Khorasani has argued that the rhythmic structures of early twentieth-century Persian classical music were more fluid than previously recognized. Analyzing 162 wax cylinder recordings made between 1906 and 1928 in Tehran and Isfahan, she found that performers routinely shifted between duple and triple meters within a single dastgah performance — a practice that later pedagogical treatises, written primarily in the 1950s and 1960s, described as incorrect or unorthodox. Nassiri-Khorasani contends that these treatises, which became the standard references for conservatory instruction, imposed a retrospective rigidity on the tradition by codifying norms that reflected mid-century aesthetic preferences rather than historical performance practice. She suggests that the wax cylinder evidence reveals a pre-codification era in which metric flexibility was not a deviation but a defining characteristic of the art form.', $lyceon_json$[{"key":"A","text":"Wax cylinder recordings from early twentieth-century Iran demonstrate that rhythmic flexibility was a standard feature of Persian classical music before later pedagogical treatises imposed stricter metric conventions."},{"key":"B","text":"The 1950s treatises on Persian classical music were written by scholars who had never heard the wax cylinder recordings from the early 1900s."},{"key":"C","text":"Performers in Tehran and Isfahan between 1906 and 1928 preferred triple meter over duple meter in most dastgah performances."},{"key":"D","text":"Farah Nassiri-Khorasani has proposed that conservatory instruction in Persian classical music should return to using wax cylinder recordings as primary teaching materials."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage''s central argument is that early recordings show rhythmic flexibility was standard practice in Persian classical music, and that later treatises retrospectively imposed rigidity that did not reflect the historical tradition. The option about wax cylinder evidence revealing pre-codification metric flexibility captures this main idea. The option claiming treatise authors never heard the recordings introduces a biographical claim nowhere stated in the passage. The option about performers preferring triple meter misrepresents the text, which describes performers shifting between duple and triple meters, not favoring one over the other. The option about Nassiri-Khorasani proposing wax cylinders as teaching materials goes beyond the passage — she argues the recordings reveal historical practice, but the text does not describe any specific pedagogical recommendation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GI5FG4', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two passages?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HDOLSA', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Ethnomusicologist Darren Okafor spent four years recording ceremonial drum patterns among the Dagomba people of northern Ghana _____ the rhythmic sequences he documented have since been incorporated into a digital archive maintained by the University of Cape Coast.', $lyceon_json$[{"key":"A","text":"Ghana, the"},{"key":"B","text":"Ghana the"},{"key":"C","text":"Ghana. The"},{"key":"D","text":"Ghana, the,"}]$lyceon_json$::jsonb, 'C', NULL, E'Two independent clauses flank the blank: one describing Okafor''s fieldwork and another describing how his documented sequences were incorporated into a digital archive. A period correctly separates these independent clauses into distinct sentences. A comma alone ("Ghana, the") produces a comma splice because no coordinating conjunction follows. Omitting all punctuation ("Ghana the") fuses two independent clauses into a run-on sentence. Adding commas on both sides of "the" ("Ghana, the,") not only creates a comma splice but also incorrectly isolates the article "the" as though it were a parenthetical element, disrupting the grammar of the second clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HJI247', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Geochemist Priya Venkataraman collected sulfur isotope samples from seventeen volcanic vents along the Mid-Atlantic Ridge _____ her findings suggested that deep-mantle plumes contribute more sulfur to oceanic crust formation than previously estimated.', $lyceon_json$[{"key":"A","text":"Ridge, her"},{"key":"B","text":"Ridge her"},{"key":"C","text":"Ridge. Her"},{"key":"D","text":"Ridge; and, her"}]$lyceon_json$::jsonb, 'C', NULL, E'The blank separates two independent clauses: one ending with "Ridge" and another beginning with "her findings suggested." A period correctly divides these into two complete sentences. Using only a comma between them ("Ridge, her") creates a comma splice, which violates standard sentence boundary conventions. Removing all punctuation ("Ridge her") produces a fused sentence, joining two independent clauses with no punctuation or conjunction. Adding a semicolon followed by "and" plus an unnecessary comma ("Ridge; and, her") is redundant and incorrectly punctuated: a semicolon already serves as a clause separator and should not be paired with a coordinating conjunction, and the comma after "and" improperly interrupts the clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HRMCNT', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at a Chilean observatory announced in 2024 that they had detected an unusual pattern of radio emissions from a white dwarf star designated LP 40-365, located roughly 98 light-years from Earth. Unlike typical white dwarfs, which emit little detectable radio energy, LP 40-365 produced periodic bursts at 1.4 gigahertz intervals that lasted approximately eleven seconds each. The team attributed these bursts to the star''s extraordinarily rapid rotation — it completes one full revolution every 8.9 minutes — which generates a magnetic field strong enough to accelerate charged particles along its poles, producing focused beams of radio waves.', $lyceon_json$[{"key":"A","text":"A white dwarf star near Earth has been found to emit unusual radio bursts, which researchers attribute to its exceptionally fast rotation and the resulting magnetic field."},{"key":"B","text":"White dwarf stars are generally unable to produce radio emissions because they lack the rotational speed needed to generate magnetic fields."},{"key":"C","text":"The Chilean observatory that detected LP 40-365's emissions specializes in monitoring stars within 100 light-years of Earth."},{"key":"D","text":"Charged particles accelerated along a star's poles always produce radio waves at a frequency of 1.4 gigahertz."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes the detection of unusual radio bursts from white dwarf LP 40-365 and explains that these bursts are caused by the star''s rapid rotation generating a strong magnetic field. The option about surprising radio bursts linked to fast rotation captures this central point. The option claiming white dwarfs generally cannot produce radio emissions overstates what the passage says — the text notes that typical white dwarfs emit little detectable radio energy, not that they are unable to do so. The option about the observatory''s specialization fabricates information not present in the passage. The option asserting that pole-accelerated particles always produce 1.4-gigahertz radio waves generalizes a single observation into a universal rule unsupported by the text.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JU1ILX', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second sentence in the passage ("Kimura demonstrated . . . three-dimensional objects")?', E'Cognitive psychologist Satoshi Kimura challenged the prevailing view that spatial reasoning and verbal reasoning are processed by entirely independent neural networks. Kimura demonstrated through functional imaging of 83 participants that regions of the left temporal cortex — traditionally associated with language processing — showed significant activation when subjects mentally rotated three-dimensional objects. This finding, Kimura contends, implies that spatial cognition partially recruits linguistic infrastructure, a possibility that could reshape how educators design curricula for students with language-processing disorders.', $lyceon_json$[{"key":"A","text":"It provides the experimental evidence supporting the challenge introduced in the first sentence"},{"key":"B","text":"It qualifies the first sentence by acknowledging a limitation of Kimura's methodology"},{"key":"C","text":"It presents a counterargument to Kimura's position from a competing researcher"},{"key":"D","text":"It restates the prevailing view that the first sentence describes"}]$lyceon_json$::jsonb, 'A', NULL, E'The first sentence states that Kimura challenged the prevailing view about independent neural networks. The second sentence supports that challenge by describing the specific experimental finding — left temporal cortex activation during spatial tasks — that serves as evidence. Qualifying the first sentence by identifying a limitation misreads the passage; the second sentence strengthens Kimura''s challenge rather than weakening it. Presenting a counterargument from a competing researcher is not supported by the text; the second sentence continues to describe Kimura''s own work. Restating the prevailing view contradicts the passage''s logic; the second sentence provides evidence against the prevailing view, not a restatement of it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KBNOAB', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Petra Lindgren has documented the nesting habits of hawksbill sea turtles along the southeastern coast of Madagascar. Over seven consecutive breeding seasons, she recorded a 41% increase in the number of nests at one particular beach near Andevoranto. _______ Lindgren attributes this growth to a community-led initiative that installed predator-proof barriers around nesting sites in 2018.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"For this reason,"},{"key":"C","text":"According to Lindgren,"},{"key":"D","text":"On the other hand,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence before the blank presents a factual observation -- a 41% increase in nests -- and the sentence after the blank offers Lindgren''s interpretation of that observation, attributing the growth to a specific community initiative. "According to Lindgren," correctly signals that the following claim is Lindgren''s stated view about the cause of the increase. "Nevertheless," implies that the subsequent statement persists despite an obstacle, but Lindgren''s attribution is an explanation, not a concession. "For this reason," suggests that the nesting increase itself caused the attribution, reversing the logical relationship between the observation and the explanation. "On the other hand," implies a contrast, but there is no opposing perspective being introduced.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LZRND8', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the passage, "sustained" most nearly means', E'The cellist sustained a single note for nearly seventeen seconds, filling the recital hall with a resonance so steady that several audience members later remarked they could feel the vibration in their sternums.', $lyceon_json$[{"key":"A","text":"suffered"},{"key":"B","text":"maintained"},{"key":"C","text":"nourished"},{"key":"D","text":"contradicted"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes a cellist holding a single note for an extended duration, producing a steady resonance. "Maintained" correctly captures the sense of keeping something going continuously over time. "Suffered" means to undergo pain or hardship, which is incoherent when applied to holding a musical note. "Nourished" means to provide food or sustenance for growth, which does not apply to the act of prolonging a sound. "Contradicted" means to assert the opposite of a statement, which has no connection to holding a note steady.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N0FVM5', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the main reason Okoro and Petersen proposed to explain the disparity they observed?', E'Industrial ecologists Chidinma Okoro and Lars Petersen analyzed municipal recycling data from 47 cities across seven West African nations between 2016 and 2022. They found that cities with populations under 250,000 recycled an average of 31% of their plastic waste, while cities exceeding one million residents recycled only 14%. Okoro and Petersen attributed this gap primarily to differences in waste collection infrastructure: smaller cities tended to rely on decentralized, community-operated sorting cooperatives that processed materials close to the point of generation, whereas larger cities depended on centralized facilities that required long-haul transport of unsorted waste — a process in which significant quantities of recyclable material were lost to contamination or diverted to landfills before reaching the processing stage.', $lyceon_json$[{"key":"A","text":"Larger cities generate proportionally more non-recyclable plastic types than smaller cities due to differences in consumer purchasing patterns."},{"key":"B","text":"The decentralized collection systems common in smaller cities process waste closer to its source, reducing material loss, while centralized systems in larger cities lose recyclable material during long-distance transport."},{"key":"C","text":"Smaller cities benefit from stronger government regulations requiring residents to sort plastic waste before collection."},{"key":"D","text":"Recycling cooperatives in smaller cities receive more international funding per capita than centralized facilities in larger cities."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage explicitly states that Okoro and Petersen attributed the recycling disparity to differences in waste collection infrastructure — specifically that decentralized cooperatives in smaller cities process waste near its source, while centralized facilities in larger cities lose recyclable material during long-haul transport. The option about non-recyclable plastic types and consumer purchasing patterns introduces factors not discussed in the passage. The option about stronger government regulations is unsupported; the passage does not mention regulatory differences. The option about international funding introduces an economic factor that the passage never addresses.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OJWJCH', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which quotation from an art historian, if true, would most directly support the claim that Osorio''s sculptural technique was influenced by traditional Oaxacan woodcarving?', E'The Mexican-American sculptor Diego Osorio gained recognition in the 1990s for large-scale wooden figures carved from single blocks of reclaimed Douglas fir. Art critics have noted that Osorio''s technique of leaving visible tool marks on finished surfaces and applying water-based aniline dyes in vivid, contrasting colors bears a strong resemblance to the methods used by Oaxacan alebrije carvers, who produce brightly painted fantastical animal figures. Osorio himself has acknowledged spending several formative months in Oaxaca as a young apprentice, though he has characterized his mature work as distinct from the alebrije tradition.', $lyceon_json$[{"key":"A","text":"\"Osorio's palette of aniline dyes and his deliberate preservation of chisel strokes directly echo the surface treatment characteristic of Oaxacan alebrije workshops, where he trained in his early twenties.\""},{"key":"B","text":"\"The monumental scale of Osorio's figures sets his work apart from virtually all contemporary woodcarving traditions in the Americas.\""},{"key":"C","text":"\"Reclaimed Douglas fir is rarely used in Oaxacan carving, which traditionally relies on the soft wood of the copal tree.\""},{"key":"D","text":"\"Osorio's decision to depict human figures rather than animals represents a clear departure from the alebrije tradition.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The claim concerns Oaxacan influence on Osorio''s technique. The quotation connecting his aniline dye palette and preserved chisel strokes directly to Oaxacan alebrije workshop methods, and confirming his training there, provides the most direct support. The quotation about monumental scale distinguishing his work addresses what makes him different, not what links him to Oaxacan traditions. The quotation about different wood species highlights a material distinction between Osorio and Oaxacan carvers, which would weaken rather than support the influence claim. The quotation about depicting human figures rather than animals points to a departure from the alebrije tradition, which again does not support the claim of influence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ORXBB6', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The ceramic fragments that archaeologist Linnea Sjostrom unearthed from a Bronze Age kiln site near _____ were later matched through spectrographic analysis to clay deposits found exclusively along the banks of the Lule River, more than three hundred kilometers to the north.', $lyceon_json$[{"key":"A","text":"Ostersund, Sweden,"},{"key":"B","text":"Ostersund, Sweden"},{"key":"C","text":"Ostersund Sweden,"},{"key":"D","text":"Ostersund Sweden"}]$lyceon_json$::jsonb, 'A', NULL, E'When a city-country (or city-state) pair appears mid-sentence, Standard English requires commas both before and after the country name: the country is treated as a parenthetical element set off by a pair of commas. Here, "Ostersund, Sweden" must be followed by a closing comma because the sentence continues with "were later matched." Omitting the comma after "Sweden" ("Ostersund, Sweden were") fails to close the parenthetical and incorrectly merges the geographic aside into the verb phrase. Omitting the comma between city and country ("Ostersund Sweden,") violates the convention for punctuating geographic pairs. Omitting both commas ("Ostersund Sweden were") removes all required punctuation from the geographic pair, producing an improperly fused construction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2P9UU5C', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeologist Fumiko Watanabe has argued that the obsidian trade routes connecting central Anatolia to the Levant during the Pre-Pottery Neolithic were maintained not by centralized elites but by kin-based reciprocal exchange networks. Some scholars have challenged this interpretation, noting that the volume and standardization of obsidian artifacts at sites like Ain Ghazal imply a degree of logistical coordination beyond the capacity of informal kin groups. _______ Watanabe has pointed out that ethnographic studies of modern gift economies among highland Papua New Guinean communities document the movement of comparable volumes of stone material over similar distances without any centralized authority, undermining the assumption that high volume necessarily implies elite coordination.', $lyceon_json$[{"key":"A","text":"Granted,"},{"key":"B","text":"In rebuttal,"},{"key":"C","text":"Specifically,"},{"key":"D","text":"To illustrate,"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence before the blank presents a scholarly challenge to Watanabe''s thesis -- critics argue that artifact volume and standardization imply centralized coordination. The sentence after the blank presents Watanabe''s counterargument, using ethnographic evidence to undermine the critics'' assumption. "In rebuttal," correctly signals that Watanabe is directly disputing the critics'' objection with contrary evidence. "Granted," introduces a concession, but Watanabe is not conceding the critics'' point; she is actively refuting it with ethnographic parallels. "Specifically," would narrow or detail a preceding claim, but Watanabe is not elaborating on the critics'' argument; she is opposing it. "To illustrate," introduces an example of a previously stated generalization, but Watanabe is not illustrating the critics'' point; she is using the ethnographic case as a counterexample to challenge their reasoning.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q5084L', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing an informational paragraph about a recent engineering achievement and wants to explain what makes the achievement noteworthy. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QQA2PR', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the restoration crew arrived at the seventeenth-century farmstead outside Bruges, rainwater _____ through a gap in the slate roof for nearly two weeks, warping several of the original oak ceiling beams beyond repair.', $lyceon_json$[{"key":"A","text":"has been seeping"},{"key":"B","text":"had been seeping"},{"key":"C","text":"was seeping"},{"key":"D","text":"seeped"}]$lyceon_json$::jsonb, 'B', NULL, E'The construction "By the time the restoration crew arrived" signals that one past action was already in progress before another past event occurred. The past perfect progressive ("had been seeping") is the correct tense to indicate an ongoing action that began before and continued up to a reference point in the past. The present perfect progressive ("has been seeping") incorrectly anchors the action to the present rather than to the past moment when the crew arrived. The past progressive ("was seeping") indicates simultaneous action with the crew''s arrival but does not convey the duration established by "for nearly two weeks." The simple past ("seeped") treats the seeping as a completed single event and fails to express the ongoing, durational nature of the action leading up to the crew''s arrival.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UERO8K', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Historians examining parish registers from seventeenth-century Cornwall have found that the surnames of tin miners'' families were distributed across parishes in patterns closely matching the locations of known tin lode deposits. However, the surnames of families involved in the wool trade — which was equally prevalent in Cornwall during this period — showed no comparable geographic clustering and instead appeared in roughly equal proportions throughout the county. The historians concluded that ________', $lyceon_json$[{"key":"A","text":"tin mining tied families to specific locations dictated by the geology of ore deposits, whereas the wool trade allowed families to operate from any location with adequate grazing land, which was widely available across Cornwall."},{"key":"B","text":"wool trading families in seventeenth-century Cornwall changed their surnames more frequently than tin mining families, making geographic tracking of wool families unreliable."},{"key":"C","text":"tin mining was a more profitable occupation than wool trading in seventeenth-century Cornwall, which explains why mining families remained in fixed locations."},{"key":"D","text":"parish registers in Cornwall were more carefully maintained in mining communities than in wool-trading communities during the seventeenth century."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts the geographic clustering of mining surnames near ore deposits with the even distribution of wool-trade surnames. The logical conclusion is that mining required proximity to fixed geological resources, while wool trading could be conducted anywhere grazing land was available — and Cornwall had grazing land throughout the county. The option about wool families changing surnames introduces an unsupported claim about naming practices not mentioned in the passage. The option about mining profitability introduces an economic factor the passage does not discuss, and higher income does not logically explain geographic fixity. The option about differential record-keeping quality suggests the data itself is unreliable, which contradicts the historians'' willingness to draw conclusions from the registers.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VW1ST1', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the passage?', E'For decades, economists assumed that workers who lost manufacturing jobs to automation would transition into service-sector employment within a few years. This assumption underpinned numerous government retraining programs launched in the 1990s and 2000s. A 2022 longitudinal study by labor economist Damaris Okonkwo, however, tracked 4,700 displaced autoworkers in three Midwestern states over fourteen years and found that fewer than thirty-one percent had secured stable service-sector employment by the end of the study period. Okonkwo argues that the skills gap between manufacturing and service work is wider than prior models acknowledged.', $lyceon_json$[{"key":"A","text":"It introduces a widely held economic assumption, notes policy built on that assumption, and then presents research findings that undermine it"},{"key":"B","text":"It proposes a new theory of labor markets and defends it with statistical evidence from multiple studies"},{"key":"C","text":"It chronicles the decline of the American manufacturing sector from the 1990s to the present"},{"key":"D","text":"It evaluates the success of government retraining programs and recommends improvements"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage follows a three-part structure: it states the long-held assumption about workforce transitions, notes the retraining programs built on that assumption, and then introduces Okonkwo''s study showing the assumption was overly optimistic. Proposing a new theory and defending it with multiple studies mischaracterizes the passage, which cites only one study and challenges an existing assumption rather than advancing a novel theory. Chronicling the decline of manufacturing overstates the scope — the passage focuses on a specific assumption about displaced workers, not a broad historical narrative. Evaluating retraining programs and recommending improvements goes beyond what the passage does; it mentions programs as context but does not assess their effectiveness or suggest reforms.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WCSIPZ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The provost insisted that the university _____ its tenure review procedures before the end of the academic year so that incoming faculty members would have clear expectations regarding the documentation required for promotion.', $lyceon_json$[{"key":"A","text":"overhauls"},{"key":"B","text":"overhauled"},{"key":"C","text":"overhaul"},{"key":"D","text":"would overhaul"}]$lyceon_json$::jsonb, 'C', NULL, E'The verb "insisted" followed by "that" introduces a subjunctive clause, which in Standard English requires the base (uninflected) form of the verb regardless of the subject''s person or number. Because "the university" is the subject of this mandative subjunctive clause, the correct form is the bare infinitive "overhaul." The third-person singular present indicative "overhauls" would be appropriate in a simple declarative statement but is incorrect in a subjunctive clause following a verb of demand or insistence. The past-tense "overhauled" incorrectly shifts the clause into the indicative past, misrepresenting the provost''s demand as a completed action rather than a mandate. The modal construction "would overhaul" introduces a conditional auxiliary that is not standard in mandative subjunctive clauses, which require the uninflected base form without modal verbs.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WD9LQ7', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Geochemists at a Norwegian university studying sediment cores from Lake Torneträsk in northern Sweden noticed that layers deposited between 536 and 545 CE contained concentrations of volcanic sulfate aerosols roughly four times higher than those in adjacent centuries. The researchers hypothesized that sustained volcanic aerosol loading during this decade suppressed summer temperatures in Scandinavia enough to shorten the growing season for barley, the primary cereal crop of the region''s early medieval communities, potentially triggering the widespread settlement abandonments documented in archaeological surveys of the area.', $lyceon_json$[{"key":"A","text":"Pollen records from Lake Torneträsk sediments show a sharp decline in barley pollen between 536 and 545 CE, followed by a gradual recovery after 560 CE."},{"key":"B","text":"Volcanic sulfate aerosols in Antarctic ice cores from the same period are present at concentrations even higher than those found in Lake Torneträsk."},{"key":"C","text":"Archaeological surveys have determined that the settlements abandoned near Lake Torneträsk were reoccupied by different cultural groups around 620 CE."},{"key":"D","text":"Barley cultivation in modern northern Sweden remains viable at summer temperatures up to two degrees Celsius below current averages."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis proposes a causal chain from volcanic aerosols to suppressed temperatures to shortened barley growing seasons to settlement abandonment. Pollen records showing a sharp decline in barley pollen during precisely the period of elevated aerosol loading would directly support the link between aerosol-driven cooling and reduced barley cultivation. The finding about Antarctic ice core concentrations addresses the global extent of volcanism but does not connect aerosol loading to barley or settlements in Scandinavia. The finding about later reoccupation by different groups addresses post-abandonment history without bearing on what caused the original abandonment. The finding about modern barley viability at lower temperatures would actually weaken the hypothesis by suggesting barley can tolerate cooling, undermining the proposed mechanism.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XHW3A0', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the passage, "charged" most nearly means', E'The ambassador''s farewell address was charged with an urgency that surprised even her closest advisors. Rather than offering the customary diplomatic pleasantries, she devoted the final eleven minutes to cataloging specific treaty violations and demanding a binding arbitration timeline before the close of the fiscal quarter.', $lyceon_json$[{"key":"A","text":"billed financially"},{"key":"B","text":"accused formally"},{"key":"C","text":"suffused"},{"key":"D","text":"depleted"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes a speech that was filled with urgency — the ambassador abandoned pleasantries and pressed specific demands. "Suffused" correctly captures the sense of being permeated or filled throughout with a particular quality. "Billed financially" refers to requesting payment for goods or services, which is incoherent when applied to the emotional quality of a speech. "Accused formally" means to bring a charge or allegation against a person, but the passage describes the tone of the speech itself, not an act of accusation directed at an individual. "Depleted" means to exhaust or use up a supply, which is the opposite of the passage''s description of the speech being filled with urgency.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
